    val MAP: Map<String, DuaText> = mapOf(
        "dua_eid_takbeer" to DuaText("ईद के रास्ते मे तकबीर", "अल्लाह सबसँ महान छथि, अल्लाह सबसँ महान छथि, अल्लाह के अतिरिक्त कोनो पूज्य-प्रभु नहि अछि, आ अल्लाह सबसँ महान छथि, अल्लाह सबसँ महान छथि, आ प्रशंसा अल्लाह के लेल अछि।", "चन्द्रग्रहणक रातिसँ ईद-उल-फितरक नमाज़ धरि, विशेष रूपसँ ईदक मैदानक मार्ग पर।", "कुरानिक आदेशः'ताकि अहाँ गिनती पूरा करी आ अल्लाहक महानताक घोषणा करू'(अल-बकाराह 2:185)। इब्न मसूद (रा.) ई तकबीर कहलनि।"),
        "dua_ahsin_aqibatana" to DuaText("सभ मामिलामे अपन उद्देश्यकेँ नीक बनाउ।", "ऐ अल्लाह, हमर सभ केँ सभ मामिलामे नीक बनाउ आ संसार मे अपमान आ आख़िरत मे सजा सँ हमरा सभ केँ बचाउ।", "प्रत्येक मामिलामे नीक परिणाम लेल।", "जे केओ ई दुआ करैत अछि आ मुकदमा चलयसँ पहिने मरि जाइत अछि (मुकदमासँ सुरक्षित)।"),
        "dua_fadlika_wa_rahmatik" to DuaText("हम अहाँक अनुग्रह आ दया माँगैत छी।", "ऐ अल्लाह, हम अहाँ सँ अहाँक अनुग्रह आ दया माँगैत छी, किएक तँ अहाँक अतिरिक्त आन कोनो व्यक्ति एकर मालिक नहि अछि।", "जखन प्रावधान आ दयाक माँग करैत छी।", "जखन भोजन नहि छल तखन मेहमान पैगम्बर सल्लल्लाहु अलैहि वसल्लम लग अयलाह; ओ ई दुआ बनौलनि, आ फेर उपहार आबि गेल।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("एकटा बेदुइनकेँ सिखायल गेल शब्दसभ", "अल्लाह के अतिरिक्त ककरो पूजा करबाक अधिकार नहि अछि, केवल अल्लाह के बिना, बिना साझीदार। अल्लाह सबसँ महान छथि, बहुत प्रशंसा अल्लाह के लेल अछि; महिमावान अल्लाह, दुनिया के प्रभु अछि; आ अल्लाह के अलावा कोनो शक्ति या शक्ति नहि अछि, जे सर्वशक्तिमान, बुद्धिमान अछि।", "एक बेदुइनकेँ सिखायल गेल धिक्र आ दुआक एकटा व्यापक वाक्यांश।", "एकर बाद हुनका'अल्लाहुम्माघफिर ली वारहमनी वाहदिनी वारजुकनी'बचना सिखायल गेल।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("जे हम पहिने आ बाद मे पठौलनि ओकरा क्षमा करू।", "ऐ अल्लाह, हमरा ओ पाप क्षमा करू जे हम पहिने आ बादमे कयने छलहुँ, जे हम गुप्त रूप सँ कयलहुँ आ जे हम खुले मे कयलहुँ, हमर ज्यादतिसभ, आ जे अहाँ हमरा सँ बेसी जनैत छी से क्षमा करू। अहाँ ओ छी जे आगू बढ़बैत छी आ जे पलटैत छी; अहाँक अतिरिक्त कोनो देवता नहि अछि।", "ताशाहहुद आ सलावतक बाद, सलामक पहिने।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम नमाज़क अन्तमे ताशाहहुद आ सलमक बीच ई पाठ कयलनि।"),
        "dua_jiddi_wa_hazli" to DuaText("हमर गम्भीरता आ हमर मजाककेँ क्षमा करू।", "ऐ अल्लाह, हमरा ओहि पापसभ केँ क्षमा करू जे हम गम्भीरतापूर्वक आ मजाक मे, गलती सँ आ जानबूझ कऽ कयलहुँ-आ ई सब हमरा मे अछि।", "हर प्रकारक पापक लेल क्षमा, ज्ञात आ अज्ञात।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक व्यापक इस्तिफफर।"),
        "dua_rising_ruku_mil" to DuaText("रुकुक बाद-स्वर्ग भरि कऽ प्रशंसा करू।", "हे हमर प्रभु, आकाश भरि कऽ, पृथ्वी भरि कऽ आ तकर बाद अहाँ जे किछु चाहैत छी, से भरि कऽ अहाँक प्रशंसा कयल जाइत अछि।", "रुकूसँ उठलाक बाद'रब्बाना लकल-हमद'क संग।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम रुकूसँ उठबाक पर ई कहलनि।"),
        "dua_istiftah_kabira" to DuaText("अल्लाह महानतम छथि, बहुत प्रशंसा कयल जाइत छथि।", "अल्लाह सबसँ महान छथि, बहुत प्रशंसा अछि अल्लाह के लेल; आ महिमा अछि अल्लाह के भोर-साँझ।", "प्रार्थना शुरू करैत समय (प्रारम्भिक प्रशंसाक एकटा रूप)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि, \"एकर लेल स्वर्गक द्वार खोलि देल गेल अछि।"),
        "dua_q_ashku_bathhi" to DuaText("याकूब (अ. स.) क दुआ-हम केवल अल्लाहसँ शिकायत करैत छी।", "हम अपन दुःख आ दुखक शिकायत केवल अल्लाहसँ करैत छी।", "गहरा दुख आ अलगावमे।", "याकूब (अ. स.) युसुफ (अ. स.) सँ अलग भऽ कऽ ई कहलनि।"),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाह सबसँ नीक रक्षक छथि।", "अल्लाह सबसँ नीक रक्षक छथि आ ओ दयालु सभ पर बहुत दयालु छथि।", "जखन बच्चा वा प्रियजनकेँ यात्रा पर पठाओल जाइत अछि।", "याकूब (अ. स.) अपन पुत्रकेँ अल्लाहकेँ सौंपैत ई कहलनि।"),
        "dua_q_aqraba_rashada" to DuaText("हमर प्रभु हमरा दक्षिण दिससँ निकट दिस दिस मार्गदर्शन करू।", "भऽ सकैत अछि जे हमर प्रभु हमरा ओहि दिस मार्गदर्शन दऽ देत जे नीक व्यवहारक बेसी निकट अछि।", "जखन कोनो मामिलामे नीक तरीकाक खोज कयल जा रहल हो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ ई कहबाक लेल कहल गेल छल जे ओ भूलला पर ई कहि दियौक।"),
        "dua_q_sawa_as_sabil" to DuaText("मूसा (अ. स.) क दुआ-हमरा सही मार्ग पर मार्गदर्शन करू।", "भऽ सकैत अछि जे हमर प्रभु हमरा सही मार्ग पर लऽ जायत।", "जखन कोनो नव यात्रा या कोनो अपरिचित सड़क पर निकलैत छी।", "मूसा (ए. एस.) ई तँ कहलनि जखन ओ मद्यान दिस घुरलाह।"),
        "dua_q_not_among_wrongdoers" to DuaText("हमरा गलत काज करय वला मे नहि राखू।", "हे हमर प्रभु, हमरा अधर्मी लोक सभक बीच मे नहि राखू।", "अल्लाहसँ एकटा दुआ माँगैत अछि जे ओ एकटा गोटेकेँ अधर्मीसँ अलग रखे।", "अल्लाहसँ एकटा दुआ माँगैत अछि जे ओ एकटा गोटेकेँ अधर्मीसँ अलग रखे।"),
        "dua_q_do_not_make_us_trial" to DuaText("हमरा पर मुकदमा नहि करू।", "हे हमर प्रभु, हमरा सभ केँ अविश्वासीक लेल परीक्षा नहि बनाउ आ हमरा सभ केँ क्षमा कऽ दियौक, हे हमर प्रभु। निश्चय ही अहाँ सर्वशक्तिमान, तत्वदर्शी छी।", "इब्राहिम (अ. स.) आ हुनकर साथी सभक दुआ।", "इब्राहिम (अ. स.) आ हुनकर साथी सभक दुआ।"),
        "dua_morning_witness" to DuaText("सुबह तौहिद के गवाह", "ऐ अल्लाह, हम भोर मे अहाँ केँ, अहाँक सिंहासन धारण करै वला सभ केँ, अहाँक स्वर्गदूत सभ केँ आ अहाँक सम्पूर्ण सृष्टिकेँ एहि बातक साक्षी बनबय लेल पुकारैत छी जे अहाँ अल्लाह छी, अहाँक अतिरिक्त कोनो पूज्य-प्रभु नहि अछि, अहाँ एकलह, बिना साझीदार आ मुहम्मद सल्लल्लाहु अलैहि वसल्लम अहाँक सेवक आ रसूल छथि।", "वर्णनमे भोरमे चारि बेर एकर उल्लेख कयल गेल अछि।", "वर्णनमे भोरमे चारि बेर एकर उल्लेख कयल गेल अछि।"),
        "dua_evening_witness" to DuaText("तौहिदकेँ साँझक साक्षी", "ऐ अल्लाह, हम साँझ मे आबि कऽ अहाँक सिंहासन धारण करै वला, अहाँक स्वर्गदूत आ अहाँक सम्पूर्ण सृष्टिकेँ ई गवाही देबाक लेल पुकारलहुँ जे अहाँ अल्लाह छी, अहाँक अतिरिक्त कोनो पूज्य-प्रभु नहि अछि, अहाँ एकलह, बिना साझीदार, आ मुहम्मद सल्लल्लाहु अलैहि वसल्लम अहाँक सेवक आ रसूल छथि।", "वर्णनमे साँझमे चारि बेर एकर उल्लेख कयल गेल अछि।", "वर्णनमे साँझमे चारि बेर एकर उल्लेख कयल गेल अछि।"),
        "dua_morning_blessing" to DuaText("आशीर्वादक लेल भोरक धन्यवाद", "ऐ अल्लाह, आइ भोर हमरा वा अहाँक कोनो सृष्टिकेँ जे किछु आशीर्वाद भेटल अछि, से केवल अहाँ सँ अछि, बिना कोनो साझीदारक; तेँ समस्त प्रशंसा आ आभार अहाँक अछि।", "अल्लाह के आशीर्वाद के लेल आभार के भोर का दिकर।", "अल्लाह के आशीर्वाद के लेल आभार के भोर का दिकर।"),
        "dua_evening_blessing" to DuaText("साँझ आशीर्वाद लेल धन्यवाद", "ऐ अल्लाह, आइ साँझ हमरा वा अहाँक कोनो सृष्टिकेँ जे किछु आशीर्वाद भेटल अछि, से केवल अहाँ सँ अछि, बिना कोनो साझीदारक; तेँ समस्त प्रशंसा आ आभार अहाँक अछि।", "अल्लाह के आशीर्वाद के लेल साँझ के शुक्रगुजार।", "अल्लाह के आशीर्वाद के लेल साँझ के शुक्रगुजार।"),
